CREATE OR REPLACE FUNCTION private.permission_editor_policy() RETURNS TABLE(key text, scope text, personal boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.key,v.scope,v.personal FROM (VALUES ('leave.create','own',true),('leave.view_own','own',true),('leave.edit_own','own',true),('leave.recall','own',true),('att.create','own',true),('att.view_own','own',true),('att.edit_own','own',true),('att.witness','own',true),('order.view','own',true),('order.view_mine','own',true),('order.take','own',true),('order.update_draft','own',true),('order.submit','own',true),('order.history','own',true),('web.view','assigned',false),('web.content_view','assigned',false),('web.content_view_mine','assigned',false),('web.outline_start','assigned',false),('web.outline_submit','assigned',false),('web.post_write_start','assigned',false),('web.post_submit','assigned',false),('web.keyword_view','assigned',false),('web.keyword_open_sheet','assigned',false),('local.view','assigned',false),('local.view_mine','assigned',false),('local.post_create','assigned',false),('local.post_edit','assigned',false),('social.view','assigned',false),('social.post_view','assigned',false),('social.post_view_mine','assigned',false),('social.post_create','assigned',false),('social.post_edit','assigned',false),('social.post_start','assigned',false),('social.post_submit','assigned',false),('video.view','assigned',false),('video.view_mine','assigned',false),('video.create','assigned',false),('video.script_start','assigned',false),('video.script_submit','assigned',false),('video.submit','assigned',false),('leave.view_unit','unit',false),('ot.view_unit','unit',false)) v(key,scope,personal) JOIN base_permission_catalog b ON b.key=v.key WHERE private.org_role_permission_ready(v.key) OR private.mkt_specialty_permission_ready(v.key) $$;
REVOKE ALL ON FUNCTION private.permission_editor_policy() FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.permission_editor_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Cần đăng nhập bằng tài khoản hoạt động.' USING ERRCODE='42501'; END IF; RETURN (SELECT coalesce(jsonb_agg(to_jsonb(p)),'[]') FROM private.permission_editor_policy() p); END $$;
REVOKE ALL ON FUNCTION public.permission_editor_read() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.permission_editor_read() TO authenticated;
CREATE OR REPLACE FUNCTION private.role_editor_validate(kind text, next_permissions text[], previous_permissions text[]) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM unnest(coalesce(next_permissions,'{}')) p WHERE NOT p=ANY(coalesce(previous_permissions,'{}')) AND NOT EXISTS(SELECT 1 FROM private.permission_editor_policy() s WHERE s.key=p AND CASE WHEN kind='marketing_task' THEN private.mkt_specialty_permission_ready(p) AND s.scope<>'unit' ELSE private.org_role_permission_ready(p) END)) THEN RAISE EXCEPTION 'Quyền mới chưa có phạm vi an toàn; giữ cấu hình hiện tại hoặc chọn quyền đã kiểm chứng.' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION private.role_editor_validate(text,text[],text[]) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION private.role_new_empty_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.is_system THEN PERFORM private.role_editor_validate(NEW.role_kind,NEW.permissions,'{}'); END IF; IF NEW.role_code IS NULL THEN NEW.role_code:=NEW.id; END IF; RETURN NEW; END $$;
DO $patch$ DECLARE d text; needle text; BEGIN SELECT pg_get_functiondef('public.role_catalog_change(text,text,text,jsonb,uuid,text,text)'::regprocedure) INTO d; needle:=$old$ IF _action='create' AND proposal->>'role_kind'='position' AND coalesce(jsonb_array_length(proposal->'permissions'),0)>0 THEN RAISE EXCEPTION 'Role vị trí mới phải có permissions=[]; cấu hình sau khi tạo.'; END IF;$old$; IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'Role creation contract changed'; END IF; d:=replace(d,needle,''); needle:=$old$IF _action IN ('create','edit') THEN$old$; d:=replace(d,needle,needle||$new$
PERFORM private.role_editor_validate(proposal->>'role_kind',ARRAY(SELECT jsonb_array_elements_text(coalesce(proposal->'permissions','[]'))),coalesce(r.permissions,'{}'));
IF coalesce((proposal->>'signal_scope_all')::boolean,false) AND NOT coalesce(r.signal_scope_all,false) THEN RAISE EXCEPTION 'Không mở tất cả nhóm tín hiệu qua ma trận quyền.'; END IF;
IF _action='edit' AND proposal->'signal_scope' IS DISTINCT FROM to_jsonb(r.signal_scope) THEN RAISE EXCEPTION 'Giữ phạm vi nhóm hiện có; cấu hình phạm vi cần quy trình riêng.'; END IF;
IF _action='create' AND coalesce(jsonb_array_length(proposal->'signal_scope'),0)>0 THEN RAISE EXCEPTION 'Role mới không mặc định phạm vi tín hiệu.'; END IF;
$new$); EXECUTE d; END $patch$;
CREATE TABLE private.staff_permission_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL,target_id uuid NOT NULL, permissions text[] NOT NULL, baseline text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes',applied_at timestamptz);
REVOKE ALL ON TABLE private.staff_permission_previews FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION private.staff_permission_validate(u uuid, permissions_ text[]) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM private.supplement_permission_guard(u); IF EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=u AND use_custom AND (mode='replace' OR source_kind='legacy')) THEN RAISE EXCEPTION 'Quyền riêng cũ đang bật; cần đối chiếu và xác nhận chuyển đổi trước, không ghi đè.'; END IF; IF EXISTS(SELECT 1 FROM unnest(coalesce(permissions_,'{}')) p WHERE NOT EXISTS(SELECT 1 FROM private.permission_editor_policy() s WHERE s.key=p AND s.personal) AND NOT EXISTS(SELECT 1 FROM user_permission_overrides o WHERE o.user_id=u AND o.source_kind='supplemental' AND o.mode='additive' AND p=ANY(o.permissions))) THEN RAISE EXCEPTION 'Không cấp quyền quản trị hoặc quyền chưa có phạm vi cá nhân an toàn.' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION private.staff_permission_validate(uuid,text[]) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.account_supplement_preview(_target uuid,_permissions text[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE state_ jsonb; old_ text[]; p record; BEGIN PERFORM private.staff_permission_validate(_target,_permissions); state_:=private.supplement_permission_state(_target); SELECT permissions INTO old_ FROM user_permission_overrides WHERE user_id=_target AND use_custom AND source_kind='supplemental' AND mode='additive'; INSERT INTO private.staff_permission_previews(actor_id,target_id,permissions,baseline) VALUES(auth.uid(),_target,ARRAY(SELECT DISTINCT unnest(coalesce(_permissions,'{}')) ORDER BY 1),md5(state_::text)) RETURNING * INTO p; RETURN jsonb_build_object('id',p.id,'fingerprint',p.baseline,'affected_users',jsonb_build_array(_target),'added',to_jsonb(ARRAY(SELECT unnest(p.permissions) EXCEPT SELECT unnest(coalesce(old_,'{}')))),'removed',to_jsonb(ARRAY(SELECT unnest(coalesce(old_,'{}')) EXCEPT SELECT unnest(p.permissions))),'inactive_legacy',EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND NOT use_custom AND mode='replace'),'expires_at',p.expires_at); END $$;
REVOKE ALL ON FUNCTION public.account_supplement_preview(uuid,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.account_supplement_preview(uuid,text[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.account_supplement_save(_target uuid,_roles text[],_permissions text[],_fingerprint text,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_ jsonb; after_ jsonb; p record; roles_ text[]; BEGIN LOCK TABLE user_roles,user_permission_overrides,app_roles,profiles,biz_appointments,biz_department_members,biz_management_assignments,biz_member_affiliations IN SHARE ROW EXCLUSIVE MODE; PERFORM private.staff_permission_validate(_target,_permissions); IF coalesce(length(trim(_reason)),0)=0 OR coalesce(cardinality(_permissions),0)>600 THEN RAISE EXCEPTION 'Cần lý do và danh sách quyền hợp lệ.'; END IF; SELECT coalesce(array_agg(role_id ORDER BY role_id),'{}') INTO roles_ FROM user_roles WHERE user_id=_target AND source_kind='supplemental'; IF roles_ IS DISTINCT FROM ARRAY(SELECT DISTINCT unnest(coalesce(_roles,'{}')) ORDER BY 1) THEN RAISE EXCEPTION 'Không cấp hoặc thu hồi Role trực tiếp tại quyền bổ sung cá nhân.'; END IF; before_:=private.supplement_permission_state(_target); IF md5(before_::text) IS DISTINCT FROM _fingerprint THEN RAISE EXCEPTION 'Quyền đã thay đổi; tải lại trước khi lưu.'; END IF; SELECT * INTO p FROM private.staff_permission_previews WHERE actor_id=auth.uid() AND target_id=_target AND baseline=_fingerprint AND permissions=ARRAY(SELECT DISTINCT unnest(coalesce(_permissions,'{}')) ORDER BY 1) AND applied_at IS NULL AND expires_at>clock_timestamp() ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'Cần xem trước còn hiệu lực trước khi lưu quyền riêng.'; END IF; INSERT INTO user_permission_overrides(user_id,use_custom,permissions,mode,source_kind) VALUES(_target,cardinality(coalesce(_permissions,'{}'))>0,ARRAY(SELECT DISTINCT unnest(coalesce(_permissions,'{}')) ORDER BY 1),'additive','supplemental') ON CONFLICT(user_id) DO UPDATE SET use_custom=excluded.use_custom,permissions=excluded.permissions,mode='additive',source_kind='supplemental',updated_at=now(); after_:=private.supplement_permission_state(_target); INSERT INTO account_permission_changes(actor_id,target_id,before_data,after_data,reason) VALUES(auth.uid(),_target,before_,after_,_reason); UPDATE private.staff_permission_previews SET applied_at=clock_timestamp() WHERE id=p.id; RETURN jsonb_build_object('fingerprint',md5(after_::text),'saved',true,'affected_users',jsonb_build_array(_target),'mode','additive'); END $$;
DO $patch$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.account_supplement_read(uuid)'::regprocedure) INTO d; d:=replace(d,$old$'legacy_override',EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND source_kind='legacy' AND use_custom)$old$,$new$'legacy_override',EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND use_custom AND (source_kind='legacy' OR mode='replace')),'inactive_legacy',EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND NOT use_custom AND mode='replace')$new$); EXECUTE d; END $patch$;